const input = $input.first();
const preparedAt = Date.now();
const headers = input.json.headers || {};
let body = input.json.body;
let rawBodySource = 'json_interpretado';
if (!body || typeof body !== 'object') {
  const raw = typeof body === 'string' ? body : '';
  if (!raw) throw new Error('Corpo da interação do Slack ausente.');
  const decode = value => decodeURIComponent(value.replace(/\+/g, ' '));
  body = Object.fromEntries(raw.split('&').filter(Boolean).map(part => {
    const split = part.indexOf('=');
    return split < 0 ? [decode(part), ''] : [decode(part.slice(0, split)), decode(part.slice(split + 1))];
  }));
  rawBodySource = 'json_texto';
}
const payload = body.payload ? (typeof body.payload === 'string' ? JSON.parse(body.payload) : body.payload) : null;
if (!payload) throw new Error('Payload de interatividade do Slack ausente.');
const action = payload.actions?.[0] || {};
const slackUserId = String(payload.user?.id || '');
const triggerId = String(payload.trigger_id || '');
const state = payload.view?.state?.values || {};
const lookupMotivo = String(state.motivo_solicitacao?.motivo_solicitacao?.selected_option?.value || '').trim();
const lookupMatricula = String(state.matricula?.matricula?.value || '').replace(/\D/g, '');
let requestKind = 'unknown';
if (payload.type === 'view_submission' && payload.view?.callback_id === 'logistica_reversa_inicio') requestKind = 'lookup_submission';
else if (payload.type === 'view_submission' && payload.view?.callback_id === 'logistica_reversa_submit') requestKind = 'view_submission';
else if (payload.type === 'block_actions' && action.action_id === 'reversa_abrir_formulario' && triggerId) requestKind = 'form_request';
const slackTimestamp = String(headers['x-slack-request-timestamp'] || headers['X-Slack-Request-Timestamp'] || '');
return [{ json: {
  ...input.json,
  body,
  payload,
  request_kind: requestKind,
  trigger_id: triggerId,
  slack_user_id: slackUserId,
  action_value: String(action.value || ''),
  lookup_motivo: lookupMotivo,
  lookup_matricula: lookupMatricula,
  slack_retry: String(headers['x-slack-retry-num'] || headers['X-Slack-Retry-Num'] || '').trim() !== '',
  slack_timestamp: slackTimestamp,
  n8n_prepared_at_ms: preparedAt,
  slack_request_age_at_prepare_ms: slackTimestamp ? preparedAt - Number(slackTimestamp) * 1000 : null,
  raw_body_source: rawBodySource,
  workflow_revision: 'REV-20260917-29'
}, binary: input.binary }];

const j = $input.first().json;
// CONFIGURAÇÃO DO PORTAL DOS CORREIOS
// Nunca deixe credenciais reais neste nó em produção: use variáveis de ambiente
// ($env) ou um cofre de segredos do n8n. Os valores abaixo são exemplos.
const correiosAuth = {
  username: $env.CORREIOS_USUARIO || 'usuario@empresa.com',
  password: $env.CORREIOS_SENHA || 'TROQUE-AQUI'
};
const config = {
  portalUrl: 'https://www2.correios.com.br/encomendas/servicosonline/',
  correiosAuth,
  codAdministrativo: $env.CORREIOS_COD_ADMINISTRATIVO || '00000000',
  codigoServico: '03247', // SEDEX Reverso
  cartao: $env.CORREIOS_CARTAO_POSTAGEM || '0000000000',
  limiteValorDeclarado: 10000,
  maxCaixas: 1,
  autorizarEmbalagem: true,
  telefoneRemetente: { ddd: '11', numero: '00000000' }, // Obrigatório (DDD + 8 dígitos)
  telefoneDestinatario: { ddd: '11', numero: '00000000' }, // Obrigatório (DDD + 8 dígitos)
  avisoRecebimento: '0',
  // Unidades que recebem os equipamentos devolvidos. Substitua pelos seus endereços.
  destinos: {
    escritorio_a: { telefone: { ddd: '11', numero: '00000000' }, label: 'Escritório A - Centro', nome: 'EMPRESA EXEMPLO LTDA', logradouro: 'Rua Exemplo', numero: '100', complemento: '1º Andar', bairro: 'Centro', referencia: 'Equipe de TI', cidade: 'São Paulo', uf: 'SP', cep: '01000000', identificacao: '00000000000000' },
    escritorio_b: { telefone: { ddd: '11', numero: '00000000' }, label: 'Escritório B - Zona Oeste', nome: 'EMPRESA EXEMPLO LTDA', logradouro: 'Avenida Exemplo', numero: '200', complemento: '', bairro: 'Zona Oeste', referencia: '', cidade: 'São Paulo', uf: 'SP', cep: '05000000', identificacao: '00000000000000' }
  }
};
return [{ json: { ...j, config } }];

const j = $input.first().json;
const payload = j.payload || {};
const config = j.config || {};
const state = payload.view?.state?.values || {};
let viewMetadata = {};
try { viewMetadata = JSON.parse(payload.view?.private_metadata || '{}'); } catch (_) {}
const text = id => String(state[id]?.[id]?.value ?? '').trim();
const checked = id => (state[id]?.[id]?.selected_options || []).map(option => option.value);
const selected = id => String(state[id]?.[id]?.selected_option?.value ?? '').trim();
const digits = value => String(value || '').replace(/\D/g, '');
function moneyCents(value) {
  const raw = String(value ?? '').replace(/R\$/gi, '').replace(/\s/g, '');
  if (!raw) return null;
  let clean;
  if (/^\d{1,3}(\.\d{3})+(,\d{1,2})?$/.test(raw)) clean = raw.replace(/\./g, '').replace(',', '.');
  else if (/^\d+(,\d{1,2})?$/.test(raw)) clean = raw.replace(',', '.');
  else if (/^\d+\.\d{1,2}$/.test(raw)) clean = raw;
  else return null;
  const parts = clean.split('.');
  const cents = Number(parts[0]) * 100 + Number((parts[1] || '').padEnd(2, '0'));
  return Number.isSafeInteger(cents) ? cents : null;
}

const declaredCents = moneyCents(text('valor_declarado'));

const fields = {
  colaboradorNome: text('colaborador_nome'),
  matricula: digits(viewMetadata.matricula || text('matricula')),
  motivoSolicitacao: String(viewMetadata.motivo || selected('motivo_solicitacao')).trim(),
  modeloAtual: selected('modelo_atual') || String(viewMetadata.modelo_atual || '').trim(),
  modeloNovo: selected('modelo_novo'),
  serialNumber: text('serial_number') || String(viewMetadata.serial_number || '').trim(),
  serialNumberNovo: text('serial_number_novo'),
  observacao: text('observacao'),
  emailColaborador: text('colaborador_email').toLowerCase(),
  cep: digits(text('cep')),
  numero: text('numero'),
  equipamentos: text('equipamentos'),
  quantidadeCaixas: Number(text('quantidade_caixas')),
  valorDeclarado: declaredCents === null ? NaN : declaredCents / 100,
  valorDeclaradoCentavos: declaredCents,
  embalagem: 'inclusa',
  unidadeDestino: selected('unidade_destino') || 'escritorio_a',
  confirmado: checked('confirmacao').includes('confirmado'),
  validadeDias: Number(selected('validade'))
};
const destinoOriginal = config.destinos?.[fields.unidadeDestino] || null;
const destino = destinoOriginal ? { ...destinoOriginal, telefone: config.telefoneDestinatario } : null;
// Telefone fixo do remetente (obrigatório), no formato do portal (DDD + 8 dígitos).
config.telefonePadrao = config.telefoneRemetente || {};
const emailRemetente = fields.emailColaborador || String(config.correiosAuth?.username || '').trim();
const errors = [];
const configErrors = [];
const requiredConfig = [
  ['codAdministrativo', config.codAdministrativo],
  ['codigoServico', config.codigoServico],
  ['cartao', config.cartao],
  ['telefonePadrao.ddd', config.telefonePadrao?.ddd],
  ['telefonePadrao.numero', config.telefonePadrao?.numero],
  ['correiosAuth.username', config.correiosAuth?.username],
  ['correiosAuth.password', config.correiosAuth?.password],
  ['destino selecionado', destino]
];
for (const [name, value] of requiredConfig) {
  if (!value || String(value).includes('PREENCHER')) configErrors.push(name);
}
if (!/^\d{8}$/.test(String(config.codAdministrativo || ''))) configErrors.push('codAdministrativo deve ter 8 dígitos');
if (!/^\d{5}$/.test(String(config.codigoServico || ''))) configErrors.push('codigoServico deve ter 5 dígitos');
if (!/^\d{10}$/.test(String(config.cartao || ''))) configErrors.push('cartao deve ter 10 dígitos');
if (!/^\d{2}$/.test(digits(config.telefonePadrao?.ddd))) configErrors.push('telefonePadrao.ddd deve ter 2 dígitos');
if (!/^\d{8}$/.test(digits(config.telefonePadrao?.numero))) configErrors.push('telefonePadrao.numero deve ter 8 dígitos');
if (!/^\d{2}$/.test(digits(config.telefoneDestinatario?.ddd))) configErrors.push('telefoneDestinatario.ddd deve ter 2 dígitos');
if (!/^\d{8}$/.test(digits(config.telefoneDestinatario?.numero))) configErrors.push('telefoneDestinatario.numero deve ter 8 dígitos');
if (!destino || !/^\d{8}$/.test(digits(destino.cep))) configErrors.push('CEP do destino deve ter 8 dígitos');

if (!fields.colaboradorNome) errors.push('Nome do colaborador é obrigatório.');
if (!fields.matricula) errors.push('Matrícula é obrigatória.');
if (!fields.motivoSolicitacao) errors.push('Motivo da solicitação é obrigatório.');
if (!fields.modeloAtual) errors.push('Modelo atual é obrigatório.');
if (!fields.serialNumber) errors.push('Serial number é obrigatório.');
if (fields.emailColaborador && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(fields.emailColaborador)) errors.push('E-mail do colaborador inválido.');
if (fields.cep.length !== 8) errors.push('CEP deve ter 8 dígitos.');
if (!fields.numero) errors.push('Número do endereço é obrigatório.');
if (!fields.equipamentos) errors.push('Informe os equipamentos.');
if (!Number.isInteger(fields.quantidadeCaixas) || fields.quantidadeCaixas < 1 || fields.quantidadeCaixas > Number(config.maxCaixas || 10)) errors.push(`Quantidade de caixas deve estar entre 1 e ${config.maxCaixas || 10}.`);
if (!Number.isSafeInteger(declaredCents) || declaredCents <= 0 || declaredCents > Math.round(Number(config.limiteValorDeclarado || 10000) * 100)) errors.push('Informe um valor declarado maior que zero, dentro do limite configurado, com no máximo duas casas decimais. Ex.: 6000,50.');
if (fields.quantidadeCaixas !== 1) errors.push('Solicite uma caixa por vez e informe o valor do conteúdo dessa caixa.');
if (String(config.codigoServico) !== '03247') configErrors.push('O serviço desta automação deve ser 03247 — SEDEX Reverso');
if (!Number.isInteger(fields.validadeDias) || fields.validadeDias < 1 || fields.validadeDias > 30) errors.push('Selecione a validade da autorização entre 1 e 30 dias.');
if (!fields.confirmado) errors.push('A confirmação sobre conteúdo e restrições é obrigatória.');
if (!emailRemetente) errors.push('E-mail corporativo do solicitante não está configurado.');

const slackUserId = j.slack_user_id || payload.user?.id || '';
if (configErrors.length || errors.length) {
  return [{ json: {
    ready: false,
    slack_user_id: slackUserId,
    config_errors: configErrors,
    validation_errors: errors,
    error_message: configErrors.length ? `Configuração pendente no n8n: ${configErrors.join(', ')}` : errors.join(' ')
  } }];
}
return [{ json: {
  ready: true,
  slack_user_id: slackUserId,
  config,
  destino,
  fields,
  emailRemetente
} }];

const j = $input.first().json;
const isConfig = Array.isArray(j.config_errors) && j.config_errors.length > 0;
const title = isConfig ? 'Automação ainda não configurada' : 'Não foi possível gerar o e-ticket';
const detail = j.error_message || 'Revise os dados informados.';
return [{ json: { ...j, slackBody: { channel: j.slack_user_id, text: `${title}: ${detail}`, blocks: [ { type: 'header', text: { type: 'plain_text', text: title } }, { type: 'section', text: { type: 'mrkdwn', text: detail } } ] } } }];

const source = $('Normalizar e preparar Firecrawl').first().json;
const session = $input.first().json || {};
const sessionId = session.id || session.sessionId || session.data?.id || '';
const errorText = String(session.error?.message || session.message || session.error || 'A API do Firecrawl não devolveu um ID de sessão.');

if (!sessionId) {
  const title = 'Firecrawl não criou a sessão';
  return [{ json: {
    ...source,
    can_execute: false,
    error_message: errorText,
    slackBody: {
      channel: source.slack_user_id,
      text: title + ': ' + errorText,
      blocks: [
        { type: 'header', text: { type: 'plain_text', text: title } },
        { type: 'section', text: { type: 'mrkdwn', text: errorText } },
        { type: 'context', elements: [{ type: 'mrkdwn', text: 'Verifique a credencial Firecrawl nos três nodes Firecrawl.' }] }
      ]
    }
  } }];
}

const browserInput = {
  workflowRevision: 'REV-20260917-29',
  portalUrl: source.config.portalUrl,
  logisticaReversaUrl: source.config.logisticaReversaUrl || 'https://www2.correios.com.br/encomendas/servicosonline/logisticaReversa/default.cfm',
  codigoAdministrativo: source.config.codAdministrativo,
  username: source.config.correiosAuth?.username || source.config.username || '',
  password: source.config.correiosAuth?.password || source.config.password || '',
  codigoServico: source.config.codigoServico,
  cartao: source.config.cartao,
  validadeDias: Number(source.fields.validadeDias),
  telefonePadrao: source.config.telefonePadrao,
  destino: source.destino || source.config.destino || {},
  fields: source.fields || {},
  emailRemetente: source.emailRemetente || source.config.correiosAuth?.username || '',
  slackUserId: source.slack_user_id || '',
  dryRun: false
};

// Emissão única, com conferência dos campos críticos antes e depois do envio.
const browserCode = String.raw`const input = ${JSON.stringify(browserInput)};

let activePage = page;
const filled = [];
const notFilled = [];

const normalize = (value) => String(value || '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/\s+/g, ' ')
  .trim()
  .toLowerCase();

const scopes = () => {
  const list = [activePage];
  for (const frame of activePage.frames()) {
    if (frame !== activePage.mainFrame()) list.push(frame);
  }
  return list;
};

// Critical fields use local labels and unique matches, never the text of a whole table row.
let criticalControls = null;
let submissionAttempted = false;

function moneyCents(value) {
  const raw = String(value ?? '').replace(/R\$/gi, '').replace(/\s/g, '');
  if (!raw) return null;
  let clean;
  if (/^\d{1,3}(\.\d{3})+(,\d{1,2})?$/.test(raw)) clean = raw.replace(/\./g, '').replace(',', '.');
  else if (/^\d+(,\d{1,2})?$/.test(raw)) clean = raw.replace(',', '.');
  else if (/^\d+\.\d{1,2}$/.test(raw)) clean = raw;
  else return null;
  const parts = clean.split('.');
  const cents = Number(parts[0]) * 100 + Number((parts[1] || '').padEnd(2, '0'));
  return Number.isSafeInteger(cents) ? cents : null;
}

async function locateCriticalControls() {
  const matches = [];
  for (const scope of scopes()) {
    const result = await scope.evaluate(() => {
      const norm = value => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/\s+/g, ' ').trim().toLowerCase();
      const visible = el => !el.disabled && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== 'hidden';
      const textInput = el => el.tagName === 'INPUT' && ['text', 'number', 'tel', ''].includes(el.type) && visible(el) && !el.readOnly;
      const all = Array.from(document.querySelectorAll('input, select, textarea')).filter(visible);
      const adjacentText = (el, after) => {
        const root = el.closest('td') || el.closest('p') || el.parentElement;
        if (!root) return '';
        const local = Array.from(root.querySelectorAll('input, select, textarea')).filter(visible);
        const index = local.indexOf(el);
        const range = document.createRange();
        range.selectNodeContents(root);
        if (after) {
          range.setStartAfter(el);
          if (local[index + 1]) range.setEndBefore(local[index + 1]);
        } else {
          if (index > 0) range.setStartAfter(local[index - 1]);
          range.setEndBefore(el);
        }
        return norm(range.toString());
      };
      const label = el => norm(Array.from(el.labels || []).map(x => x.textContent).join(' ') + ' ' + (el.getAttribute('aria-label') || ''));
      const isMoneyName = el => /valor.*declar|declar.*valor/.test(norm(el.name + ' ' + el.id));
      const money = all.filter(el => textInput(el) && !/centav|decim/.test(norm(el.name + ' ' + el.id)) &&
        (isMoneyName(el) || /valor declarado/.test(label(el)) || /valor declarado/.test(adjacentText(el, false))));
      // A cents input can share the main field's name prefix. Identify it as a pair before checking uniqueness.
      const primary = money.filter(el => {
        const prev = all[all.indexOf(el) - 1];
        return !(prev && money.includes(prev) && el.maxLength === 2 && /^,$/.test(adjacentText(el, false)));
      });
      const packaging = all.filter(el => el.type === 'checkbox' &&
        (/autorizar.*aquisicao.*embalagem/.test(label(el)) || /autorizar.*aquisicao.*embalagem/.test(adjacentText(el, true)) ||
          /embalagem/.test(norm(el.name + ' ' + el.id))));
      if (!primary.length && !packaging.length) return null;
      if (primary.length !== 1 || packaging.length !== 1) return { error: 'Valor declarado ou embalagem ausente/ambíguo no formulário.' };
      const whole = primary[0];
      const next = all[all.indexOf(whole) + 1];
      const between = next ? adjacentText(next, false) : '';
      const fraction = next && textInput(next) && (next.maxLength === 2 || /centav|decim/.test(norm(next.name + ' ' + next.id))) && /^,$/.test(between) ? next : null;
      // A visible comma means the portal expects separate reais and centavos.
      if (!fraction && next && /^,$/.test(between)) return { error: 'Campo de centavos não identificado com segurança.' };
      whole.setAttribute('data-reversa-critical', 'whole');
      if (fraction) fraction.setAttribute('data-reversa-critical', 'fraction');
      packaging[0].setAttribute('data-reversa-critical', 'packaging');
      return { split: Boolean(fraction), type: whole.type };
    });
    if (result) matches.push({ scope, ...result });
  }
  if (matches.length !== 1 || matches[0].error) throw new Error(matches[0]?.error || 'Campos críticos não identificados de forma única.');
  const match = matches[0];
  return {
    whole: match.scope.locator('[data-reversa-critical="whole"]'),
    fraction: match.split ? match.scope.locator('[data-reversa-critical="fraction"]') : null,
    packaging: match.scope.locator('[data-reversa-critical="packaging"]'),
    type: match.type
  };
}

async function verifyCriticalControls() {
  if (!criticalControls) throw new Error('Campos críticos ainda não identificados.');
  const wanted = input.fields.valorDeclaradoCentavos;
  const whole = await criticalControls.whole.inputValue();
  const fraction = criticalControls.fraction ? await criticalControls.fraction.inputValue() : null;
  const actual = fraction === null ? moneyCents(whole) :
    (/^\d+$/.test(whole) && /^\d{1,2}$/.test(fraction) ? Number(whole) * 100 + Number(fraction) : null);
  const packaging = await criticalControls.packaging.isChecked();
  if (actual !== wanted || !packaging) throw new Error('Conferência bloqueou o envio: valor declarado divergente ou embalagem não autorizada.');
  return { declaredValueCents: actual, packaging: true };
}

async function fillCriticalControls() {
  const cents = input.fields.valorDeclaradoCentavos;
  if (!Number.isSafeInteger(cents) || cents <= 0) throw new Error('Valor declarado deve ser maior que zero.');
  criticalControls = await locateCriticalControls();
  // Check packaging first: the portal may recalculate/reset values when the checkbox changes.
  await criticalControls.packaging.check();
  const whole = String(Math.floor(cents / 100));
  const fraction = String(cents % 100).padStart(2, '0');
  const value = criticalControls.fraction ? whole : whole + (criticalControls.type === 'number' ? '.' : ',') + fraction;
  await criticalControls.whole.fill(value);
  await criticalControls.whole.dispatchEvent('input');
  await criticalControls.whole.dispatchEvent('change');
  await criticalControls.whole.dispatchEvent('blur');
  if (criticalControls.fraction) {
    await criticalControls.fraction.fill(fraction);
    await criticalControls.fraction.dispatchEvent('input');
    await criticalControls.fraction.dispatchEvent('change');
    await criticalControls.fraction.dispatchEvent('blur');
  }
  await verifyCriticalControls();
  filled.push('Valor declarado', 'Aquisição de embalagem');
}

function parseAuthorization(resultText) {
  const lines = resultText.split(/\r?\n/).map(raw => String(raw || '').trim()).filter(Boolean);
  const lineValue = pattern => {
    const i = lines.findIndex(line => pattern.test(normalize(line)));
    if (i < 0) return '';
    const colon = lines[i].indexOf(':');
    if (colon >= 0) return lines[i].slice(colon + 1).trim() || lines[i + 1] || '';
    return lines[i];
  };
  const declaredLine = lines.find(line => /valor declarado/.test(normalize(line))) || '';
  const rawDeclared = declaredLine.match(/R\$\s*([\d.,]+)/i)?.[1] ||
    lineValue(/valor declarado/).match(/^(?:de\s*)?(?:R\$\s*)?([\d.,]+)/i)?.[1] || '';
  const authorization = {
    code: lineValue(/codigo (?:da )?autorizacao de postagem/).match(/[\d][\d.\s]{8,}/)?.[0]?.trim() || '',
    issuedAt: lineValue(/emitido em/),
    validUntil: lineValue(/data de validade/),
    service: lineValue(/servico de encomenda/),
    quantity: lineValue(/quantidade de objetos/),
    declaredValue: rawDeclared ? 'R$ ' + rawDeclared : '',
    declaredValueCents: moneyCents(rawDeclared),
    packaging: lineValue(/aquisicao de embalagem/),
    destination: input.destino.label || ''
  };
  const issues = [];
  if (!authorization.code) issues.push('Código da autorização não recuperado.');
  if (authorization.declaredValueCents !== input.fields.valorDeclaradoCentavos) issues.push('Valor declarado retornado ausente ou diferente do informado.');
  if (normalize(authorization.packaging) !== 'sim') issues.push('Aquisição de embalagem não confirmada como Sim.');
  if (!/\b03247\b/.test(authorization.service) || !/sedex reverso/.test(normalize(authorization.service))) issues.push('SEDEX Reverso (03247) não confirmado.');
  if (!/^1$/.test(authorization.quantity)) issues.push('Quantidade de objetos diferente de 1 ou não confirmada.');
  const phoneMissing = lines.some((line, index) => /^telefone\b/.test(normalize(line)) && /nao informado/.test(normalize(line + ' ' + (lines[index + 1] || ''))));
  if (phoneMissing) issues.push('A autorização exibe telefone "Não Informado".');
  return { authorization, issues };
}

let destinationPhoneControls = null;
let destinationPhoneStatus = { filled: false, optional: false, message: '' };

async function locateDestinationPhone() {
  const found = [];
  for (const scope of scopes()) {
    const result = await scope.evaluate(() => {
      const norm = value => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/\s+/g, ' ').trim();
      const token = value => norm(value).replace(/[^a-z0-9]/g, '');
      const visible = el => !el.disabled && !el.readOnly && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== 'hidden';
      const inputs = Array.from(document.querySelectorAll('input')).filter(el => visible(el) && ['text','tel','number',''].includes(el.type));
      const destinationOnly = el => {
        for (let parent = el.parentElement; parent && parent !== document.body; parent = parent.parentElement) {
          const text = norm(parent.textContent);
          const id = token(parent.id);
          if (/^(localdestino|dadosdestinatario|dadosdestino)$/.test(id) && !/dados do remetente/.test(text)) return true;
          if (/dados do destinatario|local de entrega|dados do destino/.test(text) && !/remetente|dados do objeto|dados dos objetos/.test(text)) return true;
        }
        return false;
      };
      const meta = inputs.map(el => {
        const names = [el.name, el.id].map(token).filter(Boolean);
        const sender = names.some(name => /^(rem|sender)|remetente/.test(name));
        const recipient = names.some(name => /^dest|dest$|destino|destinatario/.test(name));
        const labels = norm(Array.from(el.labels || []).map(x => x.textContent).join(' ') + ' ' + (el.getAttribute('aria-label') || ''));
        const local = el.closest('td') || el.parentElement;
        const text = norm(local?.textContent);
        const scoped = !sender && destinationOnly(el);
        return { el, names, sender, recipient, labels, text, scoped };
      });
      const select = kind => {
        const matchesName = m => m.names.some(name => kind === 'ddd' ? /ddd|codarea/.test(name) : /telefone|fone|phone|celular|^desttel$/.test(name) && !/ddd|codarea/.test(name));
        const exactNames = kind === 'ddd' ? ['destddd', 'ddddest', 'destinatarioddd', 'ddddestinatario'] : ['desttelefone', 'destfone', 'desttel', 'telefonedest', 'destinatariotelefone', 'destcelular', 'celulardest', 'destinatariocelular'];
        const exact = meta.filter(m => !m.sender && m.names.some(name => exactNames.includes(name)));
        if (exact.length) return exact;
        const direct = meta.filter(m => !m.sender && m.recipient && matchesName(m));
        if (direct.length) return direct;
        return meta.filter(m => m.scoped && (matchesName(m) || (kind === 'ddd'
          ? /ddd|codigo de area/.test(m.labels) || m.el.maxLength === 2 && /ddd|telefone|fone/.test(m.text)
          : /telefone|fone|celular/.test(m.labels) && m.el.maxLength !== 2 || m.el.maxLength === 8 && /telefone|fone|celular/.test(m.text))));
      };
      const describe = list => list.slice(0, 12).map(m => (m.names.join('/') || 'sem-nome') + '[' + m.el.maxLength + ']');
      const candidates = describe(meta.filter(m => !m.sender && (m.recipient || m.scoped)));
      const ddd = select('ddd');
      const phone = select('phone');
      if (!ddd.length && !phone.length) return candidates.length ? { none: true, candidates } : null;
      if (ddd.length !== 1 || phone.length !== 1 || ddd[0].el === phone[0].el) return { error: 'Telefone do destinatário não identificado de forma única (DDD: ' + describe(ddd).join(', ') + '; telefone: ' + describe(phone).join(', ') + ').', candidates };
      ddd[0].el.setAttribute('data-reversa-destination-phone','ddd');
      phone[0].el.setAttribute('data-reversa-destination-phone','number');
      return { ok: true };
    });
    if (result) found.push({ scope, ...result });
  }
  const matched = found.filter(item => !item.none);
  if (matched.length !== 1 || !matched[0].ok) {
    const candidates = [...new Set(found.flatMap(item => item.candidates || []))].slice(0, 15);
    throw new Error((matched[0]?.error || 'Não localizei DDD e telefone na seção do destinatário.') + (candidates.length ? ' Campos do destinatário visíveis: ' + candidates.join(', ') : ''));
  }
  found.splice(0, found.length, matched[0]);
  return {
    ddd: found[0].scope.locator('[data-reversa-destination-phone="ddd"]'),
    number: found[0].scope.locator('[data-reversa-destination-phone="number"]')
  };
}

async function verifyDestinationPhone() {
  try {
    const expected = input.destino.telefone || {};
    const onlyDigits = value => String(value || '').replace(/\D/g, '');
    if (!destinationPhoneControls || onlyDigits(await destinationPhoneControls.ddd.inputValue()) !== onlyDigits(expected.ddd) || onlyDigits(await destinationPhoneControls.number.inputValue()) !== onlyDigits(expected.numero)) {
      throw new Error('Telefone opcional do destinatário não confirmado no formulário.');
    }
    destinationPhoneStatus = { filled: true, optional: false, message: '' };
    return true;
  } catch (error) {
    destinationPhoneStatus = { filled: false, optional: false, message: String(error.message) };
    return false;
  }
}

const destinationCepSelectors = [
  (scope) => scope.locator('input[name="destCep"]'),
  (scope) => scope.locator('input[name="destCEP"]'),
  (scope) => scope.locator('input[name="cepDestino"]')
];
let destinationCepInfo = { applied: false, reloaded: false, action: '' };

async function waitForDestinationFields(timeout = 20000) {
  const deadline = Date.now() + timeout;
  const selectors = ['input[name="desNome"]', 'input[name="desLogradouro"]', 'input[name="desDDD"]', 'input[name="desTelefone"]', 'input[name="destNome"]', 'input[name="destBairro"]'];
  do {
    let visible = 0;
    for (const selector of selectors) visible += await visibleControlCount(selector);
    if (visible >= 2) return true;
    await activePage.waitForTimeout(500);
  } while (Date.now() < deadline);
  return false;
}

// O CEP do destino faz o portal reenviar o form1 e recarregar a página em #localDestino
// (mesmo comportamento do CEP do remetente). Aplicamos o CEP antes dos demais campos
// e esperamos a recarga terminar, para nada ser preenchido numa página prestes a sumir.
async function applyDestinationCep() {
  const expected = String(input.destino.cep || '').replace(/\D/g, '');
  const control = await firstVisible(destinationCepSelectors, 3500);
  if (!control) return false;
  const current = String(await control.inputValue().catch(() => '')).replace(/\D/g, '');
  if (destinationCepInfo.applied && current === expected) return true;
  await control.evaluate((element) => { element.ownerDocument.defaultView.__reversaAntesDoCepDestino = true; }).catch(() => null);
  await control.fill(expected);
  await control.dispatchEvent('input').catch(() => null);
  await control.dispatchEvent('change').catch(() => null);
  await control.press('Tab').catch(() => null);
  await control.dispatchEvent('blur').catch(() => null);
  const action = await control.evaluate((element) => {
    const row = element.closest('tr') || element.parentElement;
    const buttons = Array.from((row || element.ownerDocument).querySelectorAll('input[type="button"], input[type="submit"], button'));
    const target = buttons.find((button) => /alteracep/i.test(button.getAttribute('onclick') || '') || /^ok$/i.test(String(button.value || button.textContent || '').trim()));
    if (!target) return '';
    target.setAttribute('data-reversa-dest-cep-ok', '1');
    return String(target.getAttribute('onclick') || target.value || target.textContent || '').replace(/\s+/g, ' ').slice(0, 120);
  }).catch(() => '');
  if (action) {
    const button = await firstVisible([(scope) => scope.locator('[data-reversa-dest-cep-ok="1"]')], 1500);
    if (button) await clickAndSettle(button, { noWaitAfter: true, loadTimeout: 30000 }).catch(() => null);
  }
  let reloaded = false;
  const deadline = Date.now() + 12000;
  while (Date.now() < deadline) {
    const samePage = await control.evaluate((element) => Boolean(element.ownerDocument.defaultView.__reversaAntesDoCepDestino)).catch(() => false);
    if (!samePage) { reloaded = true; break; }
    await activePage.waitForTimeout(400);
  }
  if (reloaded) await activePage.waitForLoadState('domcontentloaded', { timeout: 30000 }).catch(() => null);
  await waitForDestinationFields(20000);
  await activePage.waitForTimeout(600);
  destinationCepInfo = { applied: true, reloaded, action };
  return true;
}

async function destinationSnapshot() {
  const lines = [];
  for (const scope of scopes()) {
    const part = await scope.evaluate(() => {
      const norm = (value) => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/\s+/g, ' ').trim().toLowerCase();
      const out = [];
      for (const element of Array.from(document.querySelectorAll('input, select, textarea, button'))) {
        const key = String(element.name || '') + ' ' + String(element.id || '');
        const onclick = element.getAttribute('onclick') || '';
        const row = element.closest('tr') || element.parentElement;
        const rowText = norm(row && row.innerText).slice(0, 60);
        const relevant = /(^|\s)des|dest/i.test(key) || /alteracep/i.test(onclick) || (/endere|telefone|fone|celular|ddd/.test(rowText) && !/^rem/i.test(element.name || ''));
        if (!relevant) continue;
        const hidden = element.type === 'hidden' || element.getClientRects().length === 0;
        out.push([
          element.tagName.toLowerCase() + (element.type ? ':' + element.type : ''),
          element.name || element.id || '-',
          'max=' + element.maxLength,
          element.readOnly ? 'somente-leitura' : '',
          element.disabled ? 'desabilitado' : '',
          hidden ? 'oculto' : '',
          element.value ? 'com-valor' : 'vazio',
          onclick ? 'onclick=' + onclick.replace(/\s+/g, ' ').slice(0, 60) : '',
          'linha="' + rowText + '"'
        ].filter(Boolean).join(' '));
      }
      for (const row of Array.from(document.querySelectorAll('tr'))) {
        const text = norm(row.innerText);
        if (/^(endereco|telefone)/.test(text) && !row.querySelector('input, select, textarea')) out.push('texto sem campo: "' + text.slice(0, 90) + '"');
      }
      return out;
    }).catch(() => []);
    lines.push(...part);
  }
  return lines.slice(0, 30).map((line) => redact(line));
}

// Progresso gravado na própria aba: sobrevive à queda do processo do Firecrawl
