// Quantidade de caixas: identificação estrita (nome qtd/quant/caixa + rótulo), nunca o seletor de checklist.
let quantityControl = null;
let quantityInfo = { chosen: '', value: '', candidates: [] };

async function fillQuantity() {
  const expected = '1';
  const found = [];
  for (const scope of scopes()) {
    const list = await scope.evaluate(() => {
      const norm = (value) => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/\s+/g, ' ').trim().toLowerCase();
      const out = [];
      Array.from(document.querySelectorAll('input, select')).forEach((element, index) => {
        if (['hidden', 'checkbox', 'radio', 'button', 'submit', 'image'].includes(element.type) || element.disabled || element.getClientRects().length === 0) return;
        const key = norm(String(element.name || '') + ' ' + String(element.id || ''));
        const row = element.closest('tr') || element.parentElement;
        const rowText = norm(row && row.innerText).slice(0, 100);
        if (!/qtd|quant|caixa/.test(key) && !/quantidade/.test(rowText)) return;
        element.setAttribute('data-reversa-qtd', String(index));
        out.push({ index: String(index), name: element.name || element.id || '-', tag: element.tagName.toLowerCase(), key, rowText, value: String(element.value || '') });
      });
      return out;
    }).catch(() => []);
    for (const item of list) found.push({ scope, ...item });
  }
  quantityInfo.candidates = found.map((item) => item.name + ' (' + item.tag + ', valor "' + item.value.slice(0, 10) + '"): ' + item.rowText.slice(0, 70));
  const strong = found.filter((item) => /qtd|quant|caixa/.test(item.key)
    && !/checklist/.test(item.key + ' ' + item.rowText)
    && /encomenda|caixa|objeto|volume/.test(item.key + ' ' + item.rowText));
  if (strong.length !== 1) {
    notFilled.push('Quantidade de encomendas (campo não identificado de forma única). Candidatos: ' + (quantityInfo.candidates.join('; ') || 'nenhum'));
    return false;
  }
  quantityControl = strong[0].scope.locator('[data-reversa-qtd="' + strong[0].index + '"]');
  quantityInfo.chosen = strong[0].name;
  await setControl(quantityControl, expected);
  await quantityControl.dispatchEvent('input').catch(() => null);
  if (await verifyQuantity()) { filled.push('Quantidade de encomendas'); return true; }
  notFilled.push('Quantidade de encomendas (valor não confirmado em ' + quantityInfo.chosen + ': "' + quantityInfo.value + '")');
  return false;
}

async function verifyQuantity() {
  if (!quantityControl) return false;
  quantityInfo.value = String(await quantityControl.inputValue().catch(() => '')).trim();
  return quantityInfo.value === '1';
}

async function verifySenderPhone() {
  const onlyDigits = value => String(value || '').replace(/\D/g, '');
  const ddd = await firstVisible([(scope) => scope.locator('input[name="remDDD"]')], 2000);
  const number = await firstVisible([(scope) => scope.locator('input[name="remTelefone"]')], 2000);
  if (!ddd || !number) return false;
  return onlyDigits(await ddd.inputValue()) === onlyDigits(input.telefonePadrao.ddd)
    && onlyDigits(await number.inputValue()) === onlyDigits(input.telefonePadrao.numero);
