async function fillDestinationPhone() {
  const expected = input.destino.telefone || {};
  if (!/^\d{2}$/.test(expected.ddd || '') || !/^\d{8}$/.test(expected.numero || '')) throw new Error('Configure DDD e telefone de 8 dígitos para o destinatário selecionado.');
  // Nomes reais do portal: desDDD + desTelefone (fixo). desDDDCelular/desCelular não são usados.
  const fixedDdd = await firstVisible([(scope) => scope.locator('input[name="desDDD"]')], 2500);
  const fixedNumber = await firstVisible([(scope) => scope.locator('input[name="desTelefone"]')], 2500);
  destinationPhoneControls = fixedDdd && fixedNumber ? { ddd: fixedDdd, number: fixedNumber } : await locateDestinationPhone();
  for (const [control, value] of [[destinationPhoneControls.ddd, expected.ddd], [destinationPhoneControls.number, expected.numero]]) {
    await control.fill(value);
    await control.dispatchEvent('input');
    await control.dispatchEvent('change');
    await control.dispatchEvent('blur');
  }
  if (await verifyDestinationPhone()) filled.push('Destinatário - DDD', 'Destinatário - Telefone');
}

let selectedValidityControl = null;
let selectedValidityValue = '';

function optionValidityDays(option) {
  const label = normalize(option.text).match(/^(\d+)\s*(?:dias?)?$/);
  if (label) return Number(label[1]);
  // Blank or nonnumeric labels may use a numeric option value; a conflicting
  // numeric label is never overridden by the option's internal value.
  return /^\d+$/.test(String(option.value)) ? Number(option.value) : null;
}

async function verifySelectedValidity() {
  if (!selectedValidityControl) throw new Error('Validade da autorização ainda não selecionada.');
  const actual = await selectedValidityControl.evaluate(el => ({
    value: el.value,
    text: el.selectedOptions?.[0]?.textContent || ''
  }));
  if (actual.value !== selectedValidityValue || optionValidityDays(actual) !== input.validadeDias) {
    throw new Error('A validade no formulário dos Correios ficou diferente da escolhida no Slack. Nenhuma solicitação foi enviada.');
  }
}

async function fillSelectedValidity() {
  if (!Number.isInteger(input.validadeDias) || input.validadeDias < 1 || input.validadeDias > 30) {
    throw new Error('Selecione a validade da autorização entre 1 e 30 dias.');
  }
  const control = await firstVisible([
    scope => scope.locator('select[name="dataAgendamento"]')
  ], 3000);
  if (!control) throw new Error('Não localizei o campo Validade da Autorização nos Correios.');
  const options = await control.locator('option').evaluateAll(list => list.map(el => ({
    value: el.value, text: el.textContent || '', disabled: el.disabled
  })));
  const available = options.filter(option => !option.disabled && option.value !== '' && optionValidityDays(option) > 0);
  const target = available.find(option => optionValidityDays(option) === input.validadeDias);
  if (!target) {
    const days = [...new Set(available.map(optionValidityDays))].sort((a,b) => a-b);
    throw new Error('A validade escolhida (' + input.validadeDias + ' dias) não está disponível nesta solicitação dos Correios. Prazos disponíveis: ' + (days.join(', ') || 'nenhum identificado') + '. Nenhuma solicitação foi enviada.');
  }
  await control.selectOption(target.value);
  await control.dispatchEvent('input');
  await control.dispatchEvent('change');
  await control.dispatchEvent('blur');
  selectedValidityControl = control;
  selectedValidityValue = target.value;
  await verifySelectedValidity();
  filled.push('Validade da autorização');
}

async function firstVisible(factories, timeout = 1800) {
  for (const factory of factories) {
    for (const scope of scopes()) {
      try {
        const candidate = factory(scope).first();
        if (await candidate.count()) {
          await candidate.waitFor({ state: 'visible', timeout });
          return candidate;
        }
      } catch (_) {}
    }
  }
  return null;
}

async function visibleControlCount(selector) {
  let total = 0;
  for (const scope of scopes()) {
    try { total += await scope.locator(selector + ':visible').count(); } catch (_) {}
  }
  return total;
}

async function bodyText(limit = 7000) {
  const parts = [];
  for (const scope of scopes()) {
    try {
      const value = await scope.locator('body').innerText({ timeout: 1500 });
      if (value) parts.push(value);
    } catch (_) {}
  }
  return parts.join('\n').slice(0, limit);
}

function redact(value) {
  let text = String(value || '');
  for (const secret of [input.username, input.password, input.emailRemetente, input.fields.emailColaborador]) {
    if (secret) text = text.split(String(secret)).join('[dado removido]');
  }
  return text;
}

async function clickAndSettle(locator, options = {}) {
  const context = activePage.context();
  const before = new Set(context.pages());
  const loadTimeout = options.loadTimeout || 15000;
  // noWaitAfter: o clique termina sem aguardar a navegação que ele agenda.
  await locator.click(options.noWaitAfter ? { timeout: 8000, noWaitAfter: true } : { timeout: 8000 });
  await activePage.waitForLoadState('domcontentloaded', { timeout: loadTimeout }).catch(() => null);
  await activePage.waitForTimeout(1200);
  const created = context.pages().filter((candidate) => !before.has(candidate));
  if (created.length) {
    activePage = created[created.length - 1];
    await activePage.waitForLoadState('domcontentloaded', { timeout: 15000 }).catch(() => null);
    await activePage.waitForTimeout(800);
  }
}

async function findTextAction(pattern) {
  const callId = String(Date.now()) + Math.random().toString(36).slice(2, 7);
  for (const scope of scopes()) {
    const labels = await scope.evaluate((id) => Array.from(document.querySelectorAll('a, button, input[type="button"], input[type="submit"], input[type="image"]')).slice(0, 120).map((element, index) => {
      if (!element.getClientRects().length || getComputedStyle(element).visibility === 'hidden') return null;
      const key = id + '-' + index;
      element.setAttribute('data-reversa-acao', key);
      return { key, label: [element.innerText, element.value, element.title, element.alt, element.getAttribute('aria-label')].filter(Boolean).join(' ') };
    }).filter(Boolean), callId).catch(() => []);
    const match = labels.find((item) => pattern.test(normalize(item.label)));
    if (match) return scope.locator('[data-reversa-acao="' + match.key + '"]').first();
  }
  return null;
}

async function chooseIntermediaryRoute() {
  const noPackaging = normalize(input.fields.embalagem) === 'nenhuma';
  const candidates = [];
  for (const scope of scopes()) {
    const links = scope.locator('a');
    const count = Math.min(await links.count().catch(() => 0), 160);
    for (let index = 0; index < count; index++) {
      const link = links.nth(index);
      try {
        if (!(await link.isVisible())) continue;
        const meta = await link.evaluate((element) => {
          const parent = element.closest('li, p, tr, div') || element.parentElement;
          const previous = element.previousSibling && element.previousSibling.textContent ? element.previousSibling.textContent : '';
          return {
            label: element.innerText || element.textContent || '',
            href: element.href || element.getAttribute('href') || '',
            onclick: element.getAttribute('onclick') || '',
            context: [previous, parent ? (parent.innerText || parent.textContent || '') : ''].join(' ')
          };
        });
        const combined = normalize([meta.label, meta.href, meta.onclick, meta.context].join(' '));
        if (/clique aqui|nova plataforma|pre-?postagem|com embalagem/.test(combined)) {
          candidates.push({ link, combined, label: String(meta.label || 'clique aqui').trim() });
        }
      } catch (_) {}
    }
  }

  let selected = null;
  if (noPackaging) {
    selected = candidates.find((candidate) => /nova plataforma|pre-?postagem|ppn/.test(candidate.combined));
  } else {
    selected = candidates.find((candidate) => /e-ticket com embalagem|emitir.*com embalagem|com embalagem/.test(candidate.combined)
      && !/sem embalagem/.test(candidate.combined));
  }

  // No aviso atual dos Correios, o primeiro "clique aqui" é a PPN sem embalagem
  // e o segundo é o formulário legado com embalagem.
  const clickHere = candidates.filter((candidate) => /clique aqui/.test(candidate.combined));
  if (!selected && clickHere.length >= 2) selected = noPackaging ? clickHere[0] : clickHere[1];
  if (!selected) return { clicked: false, branch: noPackaging ? 'sem_embalagem_ppn' : 'com_embalagem_legado' };

  await clickAndSettle(selected.link);
  return {
    clicked: true,
    branch: noPackaging ? 'sem_embalagem_ppn' : 'com_embalagem_legado',
    label: selected.label
  };
}

async function controlMetadata(locator) {
  return locator.evaluate((element) => {
    const labels = element.labels ? Array.from(element.labels).map((label) => label.innerText || label.textContent || '') : [];
    if (element.id) {
      const explicit = Array.from(document.querySelectorAll('label[for]'))
        .find((label) => label.getAttribute('for') === element.id);
      if (explicit) labels.push(explicit.innerText || explicit.textContent || '');
    }
    const row = element.closest('tr') || element.closest('p') || element.parentElement;
    const fieldset = element.closest('fieldset');
    const legend = fieldset ? fieldset.querySelector('legend') : null;
    return {
      tag: String(element.tagName || '').toLowerCase(),
      type: String(element.type || '').toLowerCase(),
      id: element.id || '',
      name: element.name || '',
      placeholder: element.placeholder || '',
      aria: element.getAttribute('aria-label') || '',
      labels: labels.join(' '),
      rowText: row ? (row.innerText || row.textContent || '') : '',
      sectionText: legend ? (legend.innerText || legend.textContent || '') : ''
    };
  });
}

function scoreMetadata(meta, include, exclude = []) {
  const strong = normalize([meta.id, meta.name, meta.placeholder, meta.aria, meta.labels].join(' '));
  const context = normalize([meta.rowText, meta.sectionText].join(' '));
  let score = 0;
  for (const pattern of include) {
    if (pattern.test(strong)) score += 15;
    if (pattern.test(context)) score += 5;
  }
  for (const pattern of exclude) {
    if (pattern.test(strong)) score -= 30;
    if (pattern.test(context)) score -= 12;
  }
  return score;
}

async function bestControl(include, exclude = [], allowedTags = ['input', 'textarea', 'select']) {
  let best = null;
  let bestScore = 0;
  const callId = String(Date.now()) + Math.random().toString(36).slice(2, 7);
  for (const scope of scopes()) {
    const metas = await scope.evaluate((id) => {
      const out = [];
      const nodes = Array.from(document.querySelectorAll('input:not([type="hidden"]):not([type="submit"]):not([type="button"]):not([type="image"]), textarea, select')).slice(0, 160);
      nodes.forEach((element, index) => {
        if (!element.getClientRects().length || getComputedStyle(element).visibility === 'hidden') return;
        const labels = element.labels ? Array.from(element.labels).map((label) => label.innerText || label.textContent || '') : [];
        if (element.id) {
          const explicit = Array.from(document.querySelectorAll('label[for]')).find((label) => label.getAttribute('for') === element.id);
          if (explicit) labels.push(explicit.innerText || explicit.textContent || '');
        }
        const row = element.closest('tr') || element.closest('p') || element.parentElement;
        const fieldset = element.closest('fieldset');
        const legend = fieldset ? fieldset.querySelector('legend') : null;
        const key = id + '-' + index;
        element.setAttribute('data-reversa-cand', key);
        out.push({
          key,
          tag: String(element.tagName || '').toLowerCase(),
          type: String(element.type || '').toLowerCase(),
          id: element.id || '',
          name: element.name || '',
          placeholder: element.placeholder || '',
          aria: element.getAttribute('aria-label') || '',
          labels: labels.join(' '),
          rowText: row ? (row.innerText || row.textContent || '') : '',
          sectionText: legend ? (legend.innerText || legend.textContent || '') : ''
        });
      });
      return out;
    }, callId).catch(() => []);
    for (const meta of metas) {
      if (!allowedTags.includes(meta.tag)) continue;
      if (['password', 'checkbox', 'radio', 'file'].includes(meta.type)) continue;
      const score = scoreMetadata(meta, include, exclude);
      if (score > bestScore) {
        best = { locator: scope.locator('[data-reversa-cand="' + meta.key + '"]'), meta };
        bestScore = score;
      }
    }
  }
  return bestScore > 0 ? best : null;
}

async function setControl(locator, value) {
  const tag = await locator.evaluate((element) => String(element.tagName || '').toLowerCase());
  if (tag === 'select') {
    const options = await locator.locator('option').evaluateAll((nodes) => nodes.map((node) => ({
      value: node.value,
      text: node.textContent || ''
    })));
    const target = options.find((option) => normalize(option.value) === normalize(value))
      || options.find((option) => normalize(option.text) === normalize(value))
      || options.find((option) => normalize(option.text).includes(normalize(value)));
    if (!target) return false;
    await locator.selectOption(target.value);
  } else {
    await locator.fill(String(value));
  }
  await locator.dispatchEvent('change').catch(() => null);
  await locator.dispatchEvent('blur').catch(() => null);
  return true;
}

async function fillSemantic(label, include, value, options = {}) {
  if (value === undefined || value === null || String(value).trim() === '') {
    notFilled.push(label + ' (sem valor recebido)');
    return false;
  }
  const match = await bestControl(include, options.exclude || [], options.tags || ['input', 'textarea', 'select']);
  if (!match) {
    notFilled.push(label + ' (campo não localizado)');
    return false;
  }
  try {
    const changed = await setControl(match.locator, value);
    if (!changed) {
      notFilled.push(label + ' (opção não localizada)');
      return false;
    }
    filled.push(label);
    return true;
  } catch (_) {
    notFilled.push(label + ' (não foi possível preencher)');
    return false;
  }
}

async function selectMatchingOption(label, patterns, timeout = 8000) {
  const deadline = Date.now() + timeout;
  do {
    for (const scope of scopes()) {
      const selects = scope.locator('select');
      const count = Math.min(await selects.count().catch(() => 0), 60);
      for (let index = 0; index < count; index++) {
        const select = selects.nth(index);
        try {
          if (!(await select.isVisible())) continue;
          const options = await select.locator('option').evaluateAll((nodes) => nodes.map((node) => ({
            value: node.value,
            text: node.textContent || ''
          })));
          const target = options.find((option) => patterns.some((pattern) => pattern.test(normalize(option.value + ' ' + option.text))));
          if (!target) continue;
          await select.selectOption(target.value);
          await select.dispatchEvent('input').catch(() => null);
          await select.dispatchEvent('change').catch(() => null);
          await activePage.waitForTimeout(500);
          filled.push(label + ': ' + String(target.text).trim());
          return true;
        } catch (_) {}
      }
    }
    await activePage.waitForTimeout(500);
  } while (Date.now() < deadline);
  notFilled.push(label + ' (opção não localizada)');
  return false;
}

async function controlInLabeledRow(rowPattern, selector) {
  for (const scope of scopes()) {
    const rows = scope.locator('tr, .form-group, .campo, p');
    const count = Math.min(await rows.count().catch(() => 0), 260);
    for (let index = 0; index < count; index++) {
      const row = rows.nth(index);
      try {
        const rowText = normalize(await row.innerText());
        if (!rowPattern.test(rowText)) continue;
        const controls = row.locator(selector);
        const controlCount = Math.min(await controls.count().catch(() => 0), 8);
        for (let controlIndex = 0; controlIndex < controlCount; controlIndex++) {
          const control = controls.nth(controlIndex);
          if (await control.isVisible()) return control;
        }
      } catch (_) {}
    }
  }
  return null;
}

