async function waitForCompleteForm(timeout = 10000) {
  const deadline = Date.now() + timeout;
  let text = '';
  do {
    text = await bodyText(10000);
    if (/dados do remetente|cartao de postagem|nome para contato/.test(normalize(text))) {
      return { reached: true, text };
    }
    await activePage.waitForTimeout(500);
  } while (Date.now() < deadline);
  return { reached: false, text };
}

async function waitForSenderFields(timeout = 12000) {
  const deadline = Date.now() + timeout;
  const selectors = [
    'input[name="remNome"]',
    'input[name="remNumero"]',
    'input[name="remDDD"]',
    'input[name="remTelefone"]',
    'input[name="remEmail"]',
    'select[name="dataAgendamento"]'
  ];
  do {
    let visible = 0;
    for (const selector of selectors) visible += await visibleControlCount(selector);
    if (visible >= 2) return true;
    await activePage.waitForTimeout(500);
  } while (Date.now() < deadline);
  return false;
}

async function fillRowPair(label, rowPattern, values) {
  for (const scope of scopes()) {
    const rows = scope.locator('tr, .form-group, .campo, p');
    const count = Math.min(await rows.count().catch(() => 0), 240);
    for (let index = 0; index < count; index++) {
      const row = rows.nth(index);
      try {
        if (!rowPattern.test(normalize(await row.innerText()))) continue;
        const inputs = row.locator('input:not([type="hidden"]):not([type="button"]):not([type="submit"])');
        const visibleInputs = [];
        const inputCount = Math.min(await inputs.count(), 6);
        for (let inputIndex = 0; inputIndex < inputCount; inputIndex++) {
          if (await inputs.nth(inputIndex).isVisible()) visibleInputs.push(inputs.nth(inputIndex));
        }
        if (visibleInputs.length < values.length) continue;
        for (let valueIndex = 0; valueIndex < values.length; valueIndex++) {
          await visibleInputs[valueIndex].fill(String(values[valueIndex]));
          await visibleInputs[valueIndex].dispatchEvent('change').catch(() => null);
        }
        filled.push(label);
        return true;
      } catch (_) {}
    }
  }
  notFilled.push(label + ' (campos não localizados)');
  return false;
}

