async function detectSubmitControls() {
  const matches = [];
  const finalAction = /enviar solicitacao|gerar e-ticket|confirmar solicitacao|solicitar postagem/;
  for (const scope of scopes()) {
    const labels = await scope.evaluate(() => Array.from(document.querySelectorAll('button, input[type="button"], input[type="submit"], input[type="image"], a')).slice(0, 140)
      .filter((element) => element.getClientRects().length && getComputedStyle(element).visibility !== 'hidden')
      .map((element) => [element.innerText, element.value, element.title, element.alt].filter(Boolean).join(' '))).catch(() => []);
    for (const label of labels) if (finalAction.test(normalize(label))) matches.push(String(label).trim().slice(0, 100));
  }
  return Array.from(new Set(matches)).slice(0, 10);
}

