const request = $('Preparar interação Slack').first().json;
const payload = request.payload || {};
const state = payload.view?.state?.values || {};
const motivo = String(state.motivo_solicitacao?.motivo_solicitacao?.selected_option?.value || request.lookup_motivo || '').trim();
const matricula = String(state.matricula?.matricula?.value || request.lookup_matricula || '').replace(/\D/g, '');
const errors = [];
if (!['desligamento', 'troca_maquina'].includes(motivo)) errors.push('Selecione o motivo da solicitação.');
if (!matricula) errors.push('Informe a matrícula do colaborador.');
let viewId = '';
let viewHash = '';
if (motivo === 'desligamento') {
  const opened = $('Diagnosticar abertura de consulta').first().json;
  viewId = String(opened.view_id || '');
  viewHash = String(opened.view_hash || '');
}
return [{ json: {
  motivo,
  matricula,
  lookup_error: errors.join(' '),
  slack_user_id: request.slack_user_id,
  view_id: viewId,
  view_hash: viewHash
} }];

const lookup = $('Preparar busca por motivo').first().json;
const request = $('Preparar interação Slack').first().json;
const motivo = lookup.motivo;
const matricula = lookup.matricula;
const isExchange = motivo === 'troca_maquina';
const items = $input.all().map(item => item.json || {});

// Com onError: continueRegularOutput, uma falha da planilha chega como item de erro.
const sheetFailed = items.some(row => row && row.error !== undefined);
const sheetError = items.map(row => String(row?.error?.message || row?.error || '')).find(Boolean) || '';
const rows = items.filter(row => Object.keys(row).length && row.error === undefined);
const normalizeKey = value => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().toLowerCase();
const findKey = (row, pattern) => Object.keys(row || {}).find(key => pattern.test(normalizeKey(key)));
const authorizationKeys = ['Codigo Autorização de Postagem', 'Código Autorização de Postagem'];
const authCode = row => authorizationKeys.map(key => String(row?.[key] || '').trim()).find(Boolean) || '';
const availableRows = rows.filter(row => !authCode(row));

let error = lookup.lookup_error || (sheetFailed && !rows.length
  ? 'Não consegui consultar a planilha agora. Tente novamente em alguns instantes.' + (sheetError ? ' Detalhe: ' + sheetError.slice(0, 220) : '')
  : '');
let record = null;
let obsKey = '';

if (!error) {
  if (isExchange) {
    if (!rows.length) error = 'Matrícula não encontrada na planilha de trocas. Confira o cadastro criado pelo ServiceNow.';
    else if (!availableRows.length) error = 'A matrícula já possui uma autorização de postagem registrada.';
    else if (availableRows.length > 1) error = 'Há mais de uma linha disponível para esta matrícula. Confira a planilha antes de continuar.';
    else record = availableRows[0];
  } else {
    if (!rows.length) error = 'Matrícula não encontrada na planilha de desligados.';
    else if (rows.length > 1) error = 'Há mais de uma linha para esta matrícula na planilha de desligados. Confira a planilha antes de continuar.';
    else {
      obsKey = findKey(rows[0], /^observa/);
      if (!obsKey) error = 'Não encontrei a coluna de observações na planilha de desligados. Cabeçalhos lidos: ' + Object.keys(rows[0]).join(', ').slice(0, 300);
      else if (/c[oó]digo.*autoriza[cç][aã]o.*postagem/i.test(String(rows[0][obsKey] || ''))) error = 'Esta matrícula já possui um código de autorização registrado em ' + obsKey + '.';
      else record = rows[0];
    }
  }
}

