    { type: 'input', block_id: 'quantidade_caixas', label: { type: 'plain_text', text: 'Quantidade de caixas' }, element: textInput('quantidade_caixas', '1', { max_length: 1 }) },
    { type: 'input', block_id: 'validade', label: { type: 'plain_text', text: 'Validade da autorização (dias)' }, element: { type: 'static_select', action_id: 'validade', placeholder: { type: 'plain_text', text: 'Selecione de 1 a 30 dias' }, options: Array.from({ length: 30 }, (_, index) => ({ text: { type: 'plain_text', text: String(index + 1) + (index === 0 ? ' dia' : ' dias') }, value: String(index + 1) })) } },
    { type: 'input', block_id: 'valor_declarado', label: { type: 'plain_text', text: 'Valor declarado da caixa (R$)' }, element: textInput('valor_declarado', '', { max_length: 15, placeholder: { type: 'plain_text', text: 'Ex.: 3500,00' } }) },
    { type: 'context', elements: [{ type: 'mrkdwn', text: 'Valor maior que zero, embalagem autorizada nos Correios e uma caixa por solicitação.' }] },
    { type: 'input', block_id: 'confirmacao', label: { type: 'plain_text', text: 'Confirmação' }, element: { type: 'checkboxes', action_id: 'confirmacao', options: [{ text: { type: 'mrkdwn', text: 'Confirmo que não há conteúdo proibido e aceito as restrições.' }, value: 'confirmado' }] } }
  ];
  return {
    type: 'modal',
    callback_id: 'logistica_reversa_submit',
    title: { type: 'plain_text', text: 'Logística reversa' },
    submit: { type: 'plain_text', text: 'Gerar e-ticket' },
    close: { type: 'plain_text', text: 'Cancelar' },
    private_metadata: JSON.stringify({ owner: request.slack_user_id, motivo: 'desligamento', matricula, exchange_row_number: '', modelo_atual: '', serial_number: '' }),
    blocks
  };
}

// NOVO CAMINHO: Desligamento permanece no mesmo modal e usa views.update.
if (!isExchange) {
  const view = error ? initialView(error) : buildDismissalView(compact);
  return [{ json: {
    delivery: 'view_update',
    lookup_ok: Boolean(compact) && !error,
    slack_user_id: request.slack_user_id,
    view_id: lookup.view_id,
    update_body: { view_id: lookup.view_id, view }
  } }];
}

// Troca de máquina permanece como estava nesta revisão: DM com botão.
const value = compact ? JSON.stringify(compact) : '';
const slackBody = error || value.length > 1900 ? {
  channel: request.slack_user_id,
  text: 'Não foi possível seguir com a matrícula ' + matricula + '.',
  blocks: [
    { type: 'section', text: { type: 'mrkdwn', text: ':warning: *' + (error || 'Os dados da planilha são grandes demais para abrir o formulário. Avise o time de automação.') + '*\nExecute `/reversa-correios` novamente para tentar de novo.' } }
  ]
} : {
  channel: request.slack_user_id,
  text: 'Dados encontrados para a matrícula ' + matricula + '.',
  blocks: [
    { type: 'section', text: { type: 'mrkdwn', text: '*Dados encontrados para a matrícula ' + matricula + '.*\n*Motivo:* Troca de máquina\nClique abaixo para preencher a solicitação.' } },
    { type: 'actions', elements: [{ type: 'button', style: 'primary', action_id: 'reversa_abrir_formulario', text: { type: 'plain_text', text: 'Preencher solicitação' }, value }] }
  ]
};
return [{ json: { delivery: 'dm', slack_user_id: request.slack_user_id, lookup_ok: Boolean(compact) && !error, slackBody } }];

const original = $('Preparar registro na planilha').first().json;
const base = original.desligamentoBase || {};
const items = $input.all().map(item => item.json || {});
const sheetFailed = items.some(row => row && row.error !== undefined);
const sheetError = items.map(row => String(row?.error?.message || row?.error || '')).find(Boolean) || '';
const rows = items.filter(row => Object.keys(row).length && row.error === undefined);
if (sheetFailed && !rows.length) {
  return [{ json: { ...original, update_ready: false, error: { message: 'Falha ao revalidar a planilha de desligados após a emissão.' + (sheetError ? ' Detalhe: ' + sheetError.slice(0, 260) : '') } } }];
}
if (rows.length !== 1) {
  const reason = !rows.length
    ? 'Matrícula não encontrada ao revalidar a planilha de desligados.'
    : 'Mais de uma linha encontrada para a matrícula ao revalidar a planilha de desligados.';
  return [{ json: { ...original, update_ready: false, error: { message: reason } } }];
}

// O cabeçalho pode variar: OBSERVAÇÕES, OBSERVAÇÃO, Observações etc.
const keys = Object.keys(rows[0]);
const findKey = (pattern) => keys.find(key => pattern.test(String(key).normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().toLowerCase()));
const obsKey = findKey(/^observa/);
const dueKey = findKey(/^vencim/) || 'VENCIMENTO';
const idKey = findKey(/^matricul/) || 'MATRICULA';
if (!obsKey) {
  return [{ json: { ...original, update_ready: false, error: { message: 'Não encontrei a coluna de observações na planilha de desligados. Cabeçalhos lidos: ' + keys.join(', ').slice(0, 300) } } }];
}

const existing = String(rows[0][obsKey] || '').trim();
const formObservation = String(base.observacaoFormulario || '').trim();
const codeText = 'Código Autorização de Postagem: ' + String(base.codigoAutorizacao || '').trim();
if (!base.codigoAutorizacao) {
  return [{ json: { ...original, update_ready: false, error: { message: 'Código da autorização vazio; a planilha não foi alterada.' } } }];
}

const parts = [];
if (existing) parts.push(existing);
if (formObservation) parts.push(formObservation);
parts.push(codeText);
const observations = parts.join(' | ');

return [{ json: {
  ...original,
  update_ready: true,
  observacaoColuna: obsKey,
  desligamentoRow: {
    [idKey]: base.MATRICULA,
    [obsKey]: observations,
    [dueKey]: base.vencimento
  }
} }];

const request = $('Preparar interação Slack').first().json;
let data = {};
try { data = JSON.parse(request.action_value || '{}'); } catch (_) {}
if (!data || data.u !== request.slack_user_id) throw new Error('Este botão pertence a outra solicitação.');
const motivo = String(data.motivo || '');
const matricula = String(data.matricula || '');
const isExchange = motivo === 'troca_maquina';
const error = '';
const baseModels = ['XPS 13 9310','Dell Pro 14','Latitude 7430','Latitude 5450','Latitude 5440','Latitude 5430','Latitude 5420','Latitude 5410','Latitude 5400','Latitude 3420','Latitude 3410','Latitude 3400','HP EliteBook 840','ThinkPad E14 Gen 3','ThinkPad E14 Gen 2','ThinkPad E480','Apple MacBook Pro 14 M4','MacBook Pro 14 M3','Apple MacBook Pro M1 16','MacBookAir10,1'];
const currentModel = String(data.modeloAtual || '').trim();
const newModel = String(data.modeloNovo || '').trim();
const currentSerial = String(data.serialAtual || '').trim();
// Na troca, modelo e serial atuais já estão na planilha: seguem em private_metadata
// e só viram campo se a linha estiver sem o dado.
const carryModel = isExchange && Boolean(currentModel);
const carrySerial = isExchange && Boolean(currentSerial);
const models = [...new Set([currentModel, newModel, ...baseModels].filter(Boolean))];
const modelOptions = models.map(value => ({ text: { type: 'plain_text', text: value.slice(0, 75) }, value }));
const textInput = (action_id, initial_value, extra = {}) => ({ type: 'plain_text_input', action_id, ...(initial_value ? { initial_value: String(initial_value) } : {}), ...extra });
const selectInput = (action_id, value) => ({ type: 'static_select', action_id, placeholder: { type: 'plain_text', text: 'Selecione o modelo' }, options: modelOptions, ...(value ? { initial_option: { text: { type: 'plain_text', text: value.slice(0, 75) }, value } } : {}) });

let view;
if (error) {
  view = initialView(error);
} else {
  const blocks = [
    { type: 'section', text: { type: 'mrkdwn', text: '*Solicitação de devolução de equipamentos*\n*Motivo:* ' + (isExchange ? 'Troca de máquina' : 'Desligamento') + '\n*Matrícula:* ' + matricula + '\nDados localizados na planilha de ' + (isExchange ? 'trocas.' : 'desligados.') } },
    { type: 'input', block_id: 'unidade_destino', label: { type: 'plain_text', text: 'Unidade de destino' }, element: { type: 'static_select', action_id: 'unidade_destino', initial_option: { text: { type: 'plain_text', text: 'Escritório A - Centro' }, value: 'escritorio_a' }, options: [
      { text: { type: 'plain_text', text: 'Escritório A - Centro' }, value: 'escritorio_a' },
      { text: { type: 'plain_text', text: 'Escritório B - Zona Oeste' }, value: 'escritorio_b' }
    ] } },
  ];
  if (carryModel || carrySerial) {
    blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: '*Máquina atual (da planilha):* ' + (currentModel || 'modelo não informado') + ' · serial ' + (currentSerial || 'não informado') }] });
  }
  if (!carryModel) blocks.push({ type: 'input', block_id: 'modelo_atual', label: { type: 'plain_text', text: isExchange ? 'Modelo atual' : 'Modelo' }, element: selectInput('modelo_atual', currentModel) });
  if (!carrySerial) blocks.push({ type: 'input', block_id: 'serial_number', label: { type: 'plain_text', text: isExchange ? 'Serial atual' : 'Serial Number' }, element: textInput('serial_number', currentSerial, { max_length: 64 }) });
  if (isExchange) {
    blocks.push(
      { type: 'input', optional: true, block_id: 'modelo_novo', label: { type: 'plain_text', text: 'Modelo novo' }, element: selectInput('modelo_novo', newModel) },
      { type: 'input', optional: true, block_id: 'serial_number_novo', label: { type: 'plain_text', text: 'Serial number da máquina nova' }, element: textInput('serial_number_novo', data.serialNovo, { max_length: 64 }) }
    );
  }
  if (!isExchange) blocks.push({ type: 'input', optional: true, block_id: 'observacao', label: { type: 'plain_text', text: 'Observação' }, element: textInput('observacao', '', { multiline: true, max_length: 500 }) });
  blocks.push(
    { type: 'input', block_id: 'colaborador_nome', label: { type: 'plain_text', text: 'Nome do colaborador' }, element: textInput('colaborador_nome', data.nome, { max_length: 60 }) },
    { type: 'input', optional: true, block_id: 'colaborador_email', label: { type: 'plain_text', text: 'E-mail para receber a autorização (opcional)' }, element: textInput('colaborador_email', isExchange ? '' : data.email, { max_length: 72, placeholder: { type: 'plain_text', text: 'nome@empresa.com' } }) },
    { type: 'input', block_id: 'cep', label: { type: 'plain_text', text: 'CEP do colaborador' }, element: textInput('cep', '', { max_length: 9, placeholder: { type: 'plain_text', text: '00000000' } }) },
    { type: 'input', block_id: 'numero', label: { type: 'plain_text', text: 'Número do endereço' }, element: textInput('numero', '', { max_length: 8, placeholder: { type: 'plain_text', text: 'S/N se não houver' } }) },
    { type: 'input', block_id: 'equipamentos', label: { type: 'plain_text', text: 'Equipamentos na caixa' }, element: textInput('equipamentos', '', { multiline: true, max_length: 255, placeholder: { type: 'plain_text', text: 'Ex.: notebook e carregador' } }) },
    { type: 'input', block_id: 'quantidade_caixas', label: { type: 'plain_text', text: 'Quantidade de caixas' }, element: textInput('quantidade_caixas', '1', { max_length: 1 }) },
    { type: 'input', block_id: 'validade', label: { type: 'plain_text', text: 'Validade da autorização (dias)' }, element: { type: 'static_select', action_id: 'validade', placeholder: { type: 'plain_text', text: 'Selecione de 1 a 30 dias' }, options: Array.from({ length: 30 }, (_, index) => ({ text: { type: 'plain_text', text: String(index + 1) + (index === 0 ? ' dia' : ' dias') }, value: String(index + 1) })) } },
    { type: 'input', block_id: 'valor_declarado', label: { type: 'plain_text', text: 'Valor declarado da caixa (R$)' }, element: textInput('valor_declarado', '', { max_length: 15, placeholder: { type: 'plain_text', text: 'Ex.: 3500,00' } }) },
    { type: 'context', elements: [{ type: 'mrkdwn', text: 'Valor maior que zero, embalagem autorizada nos Correios e uma caixa por solicitação.' }] },
    { type: 'input', block_id: 'confirmacao', label: { type: 'plain_text', text: 'Confirmação' }, element: { type: 'checkboxes', action_id: 'confirmacao', options: [{ text: { type: 'mrkdwn', text: 'Confirmo que não há conteúdo proibido e aceito as restrições.' }, value: 'confirmado' }] } }
  );
  view = {
    type: 'modal', callback_id: 'logistica_reversa_submit',
    title: { type: 'plain_text', text: 'Logística reversa' }, submit: { type: 'plain_text', text: 'Gerar e-ticket' }, close: { type: 'plain_text', text: 'Cancelar' },
    private_metadata: JSON.stringify({ owner: request.slack_user_id, motivo, matricula, exchange_row_number: data.row || '', modelo_atual: carryModel ? currentModel : '', serial_number: carrySerial ? currentSerial : '' }),
    blocks
  };
}

return [{ json: {
  slack_user_id: request.slack_user_id,
  n8n_prepared_at_ms: request.n8n_prepared_at_ms,
  open_body: { trigger_id: request.trigger_id, view }
} }];

const request = $('Preparar interação Slack').first().json;
const prepared = $('Preparar convite do formulário').first().json;
const raw = $input.first().json || {};
const result = raw.body && typeof raw.body === 'object' ? raw.body : raw;
const updated = result.ok === true && Boolean(result.view?.id || prepared.view_id);
const error = updated ? '' : String(result.error?.message || result.error || result.message || 'resposta_sem_confirmacao').slice(0, 300);
const slackBody = {
  channel: request.slack_user_id,
  text: 'Não consegui atualizar o formulário de desligamento.',
  blocks: [
    { type: 'section', text: { type: 'mrkdwn', text: ':warning: *Não consegui atualizar o formulário de desligamento.*\nA consulta terminou, mas o Slack não aceitou a atualização do modal. Execute `/reversa` novamente. Nenhuma autorização foi emitida nesta etapa.' } },
    { type: 'context', elements: [{ type: 'mrkdwn', text: 'Código do Slack: ' + (error || 'não informado') + ' · view_id: ' + (prepared.view_id || 'não informado') }] }
  ]
};
return [{ json: { modal_updated: updated, slack_error: error, slackBody } }];

const request = $('Preparar interação Slack').first().json;
const motivo = request.lookup_motivo;
const matricula = request.lookup_matricula;
const view = {
  type: 'modal',
  callback_id: 'logistica_reversa_loading',
  title: { type: 'plain_text', text: 'Logística reversa' },
  close: { type: 'plain_text', text: 'Cancelar' },
  private_metadata: JSON.stringify({ owner: request.slack_user_id, motivo, matricula }),
  blocks: [
    { type: 'section', text: { type: 'mrkdwn', text: ':hourglass_flowing_sand: *Consultando a matrícula…*\nAguarde enquanto verifico a planilha de desligados.' } }
  ]
};
return [{ json: {
  slack_user_id: request.slack_user_id,
  trigger_id: request.trigger_id,
  n8n_prepared_at_ms: request.n8n_prepared_at_ms,
  slack_request_age_at_prepare_ms: request.slack_request_age_at_prepare_ms,
  open_body: { trigger_id: request.trigger_id, view }
} }];

const request = $('Preparar interação Slack').first().json;
const raw = $input.first().json || {};
const result = raw.body && typeof raw.body === 'object' ? raw.body : raw;
const opened = result.ok === true && Boolean(result.view?.id);
const error = opened ? '' : String(result.error?.message || result.error || result.message || 'resposta_sem_confirmacao').slice(0, 240);
const ageSeconds = Math.max(0, Math.round((Number(request.slack_request_age_at_prepare_ms) || 0) / 1000));
const elapsed = Date.now() - Number(request.n8n_prepared_at_ms || Date.now());
const slackBody = {
  channel: request.slack_user_id,
  text: 'Não consegui iniciar a consulta da matrícula.',
  blocks: [
    { type: 'section', text: { type: 'mrkdwn', text: ':warning: *Não consegui iniciar a consulta da matrícula.*\nExecute `/reversa-correios` novamente. Nenhuma autorização foi emitida.' } },
    { type: 'context', elements: [{ type: 'mrkdwn', text: 'Código do Slack: ' + (error || 'não informado') + ' · interação recebida há ~' + ageSeconds + ' s · ' + elapsed + ' ms desde o início desta execução · revisão REV-20260917-29' }] }
  ]
};
return [{ json: { lookup_modal_opened: opened, view_id: result.view?.id || '', view_hash: result.view?.hash || '', slack_error: error, slackBody } }];

const request = $('Preparar interação Slack').first().json;
const raw = $input.first().json || {};
const result = raw.body && typeof raw.body === 'object' ? raw.body : raw;
const opened = result.ok === true && Boolean(result.view?.id);
const error = opened ? '' : String(result.error?.message || result.error || result.message || 'resposta_sem_confirmacao').slice(0, 240);
const slackBody = {
  channel: request.slack_user_id,
  text: 'Não consegui abrir o formulário de troca.',
  blocks: [
    { type: 'section', text: { type: 'mrkdwn', text: ':warning: *Não consegui abrir o formulário de troca.*\nExecute `/reversa-correios` novamente. Nenhuma autorização foi emitida.' } },
    { type: 'context', elements: [{ type: 'mrkdwn', text: 'Código do Slack: ' + (error || 'não informado') + ' · revisão REV-20260917-29' }] }
  ]
};
return [{ json: { exchange_modal_opened: opened, slack_error: error, slackBody } }];
